CREATE TYPE public.app_role AS ENUM ('admin','corretor');
CREATE TABLE public.empresas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nome text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.empresas TO authenticated; GRANT ALL ON public.empresas TO service_role;
ALTER TABLE public.empresas ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.profiles (id uuid PRIMARY KEY, empresa_id uuid NOT NULL REFERENCES public.empresas(id), nome text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.my_empresa_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT empresa_id FROM public.profiles WHERE id = auth.uid() $$;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
CREATE POLICY empresas_view ON public.empresas FOR SELECT TO authenticated USING (id = public.my_empresa_id());
CREATE POLICY empresas_edit ON public.empresas FOR UPDATE TO authenticated USING (id = public.my_empresa_id() AND public.has_role(auth.uid(),'admin')) WITH CHECK (id = public.my_empresa_id());
CREATE POLICY profiles_view ON public.profiles FOR SELECT TO authenticated USING (empresa_id = public.my_empresa_id());
CREATE POLICY profiles_edit ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid() AND empresa_id = public.my_empresa_id());
CREATE POLICY roles_view ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid() OR (public.has_role(auth.uid(),'admin') AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.id = user_id AND p.empresa_id = public.my_empresa_id())));
CREATE FUNCTION public.bootstrap_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_empresa uuid; BEGIN INSERT INTO public.empresas(nome) VALUES ('Minha corretora') RETURNING id INTO v_empresa; INSERT INTO public.profiles(id,empresa_id,nome,email) VALUES (NEW.id,v_empresa,COALESCE(NEW.raw_user_meta_data->>'nome',split_part(NEW.email,'@',1)),COALESCE(NEW.email,'')); INSERT INTO public.user_roles(user_id,role) VALUES (NEW.id,'admin'); RETURN NEW; END $$;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.bootstrap_user();
CREATE TABLE public.clientes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), empresa_id uuid NOT NULL REFERENCES public.empresas(id), tipo text NOT NULL DEFAULT 'PF', nome text NOT NULL, documento text DEFAULT '', telefone text DEFAULT '', whatsapp text DEFAULT '', email text DEFAULT '', cidade text DEFAULT '', estado text DEFAULT '', endereco text DEFAULT '', cep text DEFAULT '', observacoes text DEFAULT '', responsavel_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.clientes TO authenticated; GRANT ALL ON public.clientes TO service_role; ALTER TABLE public.clientes ENABLE ROW LEVEL SECURITY;
CREATE POLICY clientes_empresa ON public.clientes FOR ALL TO authenticated USING (empresa_id = public.my_empresa_id()) WITH CHECK (empresa_id = public.my_empresa_id());
CREATE TABLE public.leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), empresa_id uuid NOT NULL REFERENCES public.empresas(id), nome text NOT NULL, documento text DEFAULT '', telefone text DEFAULT '', whatsapp text DEFAULT '', email text DEFAULT '', cidade text DEFAULT '', produto text DEFAULT 'Seguro Auto', origem text DEFAULT 'Outros', status text NOT NULL DEFAULT 'Novo', observacoes text DEFAULT '', responsavel_id uuid, cliente_id uuid REFERENCES public.clientes(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.leads TO authenticated; GRANT ALL ON public.leads TO service_role; ALTER TABLE public.leads ENABLE ROW LEVEL SECURITY;
CREATE POLICY leads_empresa ON public.leads FOR ALL TO authenticated USING (empresa_id = public.my_empresa_id()) WITH CHECK (empresa_id = public.my_empresa_id());
CREATE TABLE public.veiculos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), empresa_id uuid NOT NULL REFERENCES public.empresas(id), cliente_id uuid NOT NULL REFERENCES public.clientes(id), placa text NOT NULL, marca text NOT NULL DEFAULT '', modelo text NOT NULL DEFAULT '', ano integer, renavam text DEFAULT '', chassi text DEFAULT '', tipo text DEFAULT 'Automóvel', combustivel text DEFAULT '', uso text DEFAULT '', observacoes text DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.veiculos TO authenticated; GRANT ALL ON public.veiculos TO service_role; ALTER TABLE public.veiculos ENABLE ROW LEVEL SECURITY;
CREATE POLICY veiculos_empresa ON public.veiculos FOR ALL TO authenticated USING (empresa_id = public.my_empresa_id()) WITH CHECK (empresa_id = public.my_empresa_id() AND EXISTS(SELECT 1 FROM public.clientes c WHERE c.id = cliente_id AND c.empresa_id = public.my_empresa_id()));
CREATE TABLE public.apolices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), empresa_id uuid NOT NULL REFERENCES public.empresas(id), cliente_id uuid NOT NULL REFERENCES public.clientes(id), veiculo_id uuid REFERENCES public.veiculos(id), seguradora text NOT NULL, numero text NOT NULL, inicio date NOT NULL, vencimento date NOT NULL, premio numeric(12,2) NOT NULL DEFAULT 0, franquia numeric(12,2), comissao_percentual numeric(5,2) DEFAULT 0, status text NOT NULL DEFAULT 'Vigente', observacoes text DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.apolices TO authenticated; GRANT ALL ON public.apolices TO service_role; ALTER TABLE public.apolices ENABLE ROW LEVEL SECURITY;
CREATE POLICY apolices_empresa ON public.apolices FOR ALL TO authenticated USING (empresa_id = public.my_empresa_id()) WITH CHECK (empresa_id = public.my_empresa_id() AND EXISTS(SELECT 1 FROM public.clientes c WHERE c.id = cliente_id AND c.empresa_id = public.my_empresa_id()) AND (veiculo_id IS NULL OR EXISTS(SELECT 1 FROM public.veiculos v WHERE v.id = veiculo_id AND v.cliente_id = cliente_id AND v.empresa_id = public.my_empresa_id())));
CREATE TABLE public.tarefas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), empresa_id uuid NOT NULL REFERENCES public.empresas(id), cliente_id uuid REFERENCES public.clientes(id), lead_id uuid REFERENCES public.leads(id), titulo text NOT NULL, tipo text NOT NULL DEFAULT 'Outro', data date NOT NULL DEFAULT CURRENT_DATE, horario time, prioridade text NOT NULL DEFAULT 'Normal', status text NOT NULL DEFAULT 'Pendente', descricao text DEFAULT '', responsavel_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.tarefas TO authenticated; GRANT ALL ON public.tarefas TO service_role; ALTER TABLE public.tarefas ENABLE ROW LEVEL SECURITY;
CREATE POLICY tarefas_empresa ON public.tarefas FOR ALL TO authenticated USING (empresa_id = public.my_empresa_id()) WITH CHECK (empresa_id = public.my_empresa_id() AND (cliente_id IS NULL OR EXISTS(SELECT 1 FROM public.clientes c WHERE c.id = cliente_id AND c.empresa_id = public.my_empresa_id())) AND (lead_id IS NULL OR EXISTS(SELECT 1 FROM public.leads l WHERE l.id = lead_id AND l.empresa_id = public.my_empresa_id())));
CREATE TABLE public.historico_contatos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), empresa_id uuid NOT NULL REFERENCES public.empresas(id), cliente_id uuid REFERENCES public.clientes(id), lead_id uuid REFERENCES public.leads(id), tipo text NOT NULL DEFAULT 'Contato', descricao text NOT NULL, usuario_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.historico_contatos TO authenticated; GRANT ALL ON public.historico_contatos TO service_role; ALTER TABLE public.historico_contatos ENABLE ROW LEVEL SECURITY;
CREATE POLICY historico_empresa ON public.historico_contatos FOR ALL TO authenticated USING (empresa_id = public.my_empresa_id()) WITH CHECK (empresa_id = public.my_empresa_id() AND (cliente_id IS NULL OR EXISTS(SELECT 1 FROM public.clientes c WHERE c.id = cliente_id AND c.empresa_id = public.my_empresa_id())) AND (lead_id IS NULL OR EXISTS(SELECT 1 FROM public.leads l WHERE l.id = lead_id AND l.empresa_id = public.my_empresa_id())));
CREATE TABLE public.sinistros (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), empresa_id uuid NOT NULL REFERENCES public.empresas(id), cliente_id uuid NOT NULL REFERENCES public.clientes(id), veiculo_id uuid REFERENCES public.veiculos(id), apolice_id uuid REFERENCES public.apolices(id), tipo text NOT NULL DEFAULT 'Outro', data date NOT NULL DEFAULT CURRENT_DATE, protocolo text DEFAULT '', local text DEFAULT '', oficina text DEFAULT '', descricao text DEFAULT '', status text NOT NULL DEFAULT 'Aberto', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.sinistros TO authenticated; GRANT ALL ON public.sinistros TO service_role; ALTER TABLE public.sinistros ENABLE ROW LEVEL SECURITY;
CREATE POLICY sinistros_empresa ON public.sinistros FOR ALL TO authenticated USING (empresa_id = public.my_empresa_id()) WITH CHECK (empresa_id = public.my_empresa_id() AND EXISTS(SELECT 1 FROM public.clientes c WHERE c.id = cliente_id AND c.empresa_id = public.my_empresa_id()) AND (veiculo_id IS NULL OR EXISTS(SELECT 1 FROM public.veiculos v WHERE v.id = veiculo_id AND v.cliente_id = cliente_id AND v.empresa_id = public.my_empresa_id())) AND (apolice_id IS NULL OR EXISTS(SELECT 1 FROM public.apolices a WHERE a.id = apolice_id AND a.cliente_id = cliente_id AND a.empresa_id = public.my_empresa_id())));
CREATE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['empresas','profiles','clientes','leads','veiculos','apolices','tarefas','historico_contatos','sinistros'] LOOP EXECUTE format('CREATE TRIGGER touch_updated_at BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at()',t); END LOOP; END $$;
CREATE INDEX ON public.clientes(empresa_id,nome); CREATE INDEX ON public.leads(empresa_id,status); CREATE INDEX ON public.veiculos(empresa_id,cliente_id); CREATE INDEX ON public.apolices(empresa_id,vencimento); CREATE INDEX ON public.tarefas(empresa_id,data); CREATE INDEX ON public.sinistros(empresa_id,status);